CREATE DATABASE IF NOT EXISTS myportfolio CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE myportfolio;
CREATE TABLE IF NOT EXISTS admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profile(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL DEFAULT 'Your Name',age VARCHAR(30),university VARCHAR(200),programme VARCHAR(200),portrait_url VARCHAR(500) DEFAULT 'assets/images/idris-portrait.png',hero_label VARCHAR(160) DEFAULT 'COMPUTER SCIENCE STUDENT',hero_title VARCHAR(255) DEFAULT 'Building thoughtful digital experiences.',intro TEXT,about_title VARCHAR(255) DEFAULT 'Design-minded. Systems-focused.',about TEXT,about_extra TEXT,email VARCHAR(190),github_url VARCHAR(500),linkedin_url VARCHAR(500),resume_url VARCHAR(500),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,category VARCHAR(120) DEFAULT 'Project',description TEXT,technologies VARCHAR(500),image_url VARCHAR(500),image_alt VARCHAR(255),role VARCHAR(255),status VARCHAR(80) DEFAULT 'In progress',demo_url VARCHAR(500),source_url VARCHAR(500),case_study_url VARCHAR(500),sort_order INT DEFAULT 0,is_published TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS skills(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category VARCHAR(100) NOT NULL,name VARCHAR(120) NOT NULL,level VARCHAR(80),sort_order INT DEFAULT 0,is_published TINYINT(1) DEFAULT 1);
CREATE TABLE IF NOT EXISTS timeline(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(80) DEFAULT 'Education',period VARCHAR(120),title VARCHAR(180) NOT NULL,organization VARCHAR(180),details TEXT,sort_order INT DEFAULT 0,is_published TINYINT(1) DEFAULT 1);
INSERT INTO profile(name,intro,about,email,github_url,linkedin_url,resume_url) SELECT 'Your Name','Computer Science student focused on web systems, interface design, and useful software.','I am a Computer Science student interested in web systems, UI/UX, and software development.','', '', '', 'assets/documents/resume.pdf' WHERE NOT EXISTS(SELECT 1 FROM profile);
INSERT INTO projects(name,category,description,technologies,image_url,image_alt,role,status,sort_order) SELECT 'i-Gold POS System','Web System','Project details and contributions to be added.','Technologies to be confirmed','assets/images/project-placeholder.svg','Placeholder preview for i-Gold POS System','Role to be added','In progress',1 WHERE NOT EXISTS(SELECT 1 FROM projects);
INSERT INTO projects(name,category,description,technologies,image_url,image_alt,role,status,sort_order) SELECT 'SijilPro','Web System','Project details and contributions to be added.','Technologies to be confirmed','assets/images/project-placeholder.svg','Placeholder preview for SijilPro','Role to be added','In progress',2 WHERE NOT EXISTS(SELECT 1 FROM projects WHERE name='SijilPro');
INSERT INTO projects(name,category,description,technologies,image_url,image_alt,role,status,sort_order) SELECT 'Basic Dream Construction','Website','Project details and contributions to be added.','Technologies to be confirmed','assets/images/project-placeholder.svg','Placeholder preview for Basic Dream Construction','Role to be added','In progress',3 WHERE NOT EXISTS(SELECT 1 FROM projects WHERE name='Basic Dream Construction');
INSERT INTO timeline(type,period,title,organization,details,sort_order) SELECT 'Education','Current','Diploma in Computer Science','Institution to be added','',1 WHERE NOT EXISTS(SELECT 1 FROM timeline);
